python3 -c "import pandas as pd
def get_data(file_path):
    df = pd.read_excel(file_path)
    data = {}
    for year in range(1973, 2024):
        year_str = f'{year}.'
        row = df[df.iloc[:, 0].astype(str).str.strip() == year_str]
        if not row.empty:
            data[year] = float(row.iloc[0, 1])
    q2024 = []
    found_2024 = False
    for i in range(len(df)):
        val = str(df.iloc[i, 0]).strip()
        if val == '2024: I.':
            found_2024 = True
            q2024.append(float(df.iloc[i, 1]))
        elif found_2024:
            if val in ['II.', 'III.', 'IV.', 'III p.', 'IV p.']:
                q2024.append(float(df.iloc[i, 1]))
            elif ':' in val or (len(val) > 4 and not val.endswith('.')): 
                break
    if q2024:
        data[2024] = sum(q2024) / len(q2024)
        print(f'{file_path} 2024 quarters: {q2024}')
    return data

pce = get_data('ERP-2025-table10.xls')
pfi = get_data('ERP-2025-table12.xls')

print(f'PCE 1973: {pce.get(1973)}, 2023: {pce.get(2023)}, 2024: {pce.get(2024)}')
print(f'PFI 1973: {pfi.get(1973)}, 2023: {pfi.get(2023)}, 2024: {pfi.get(2024)}')
"

